// By scripts/eye-cues.mjs via the Anthropic API. Merges into ARTEFACTUM_CUES at load; never
// clobbers a hand-written cues.js entry. Load AFTER cues.js, before the app script.
(function(){var C=window.ARTEFACTUM_CUES=window.ARTEFACTUM_CUES||{style:{},culture:{},region:{},medium:{}};
var G={"style":{"Hudson River School":{"why":"Luminous, panoramic wilderness landscapes with sublime skies mark Hudson River School painting, c. 1825–1880, United States.","cues":["Vast, glowing skies dominating the canvas.","Tiny human figures dwarfed by grand nature.","Smooth, nearly invisible brushwork on lush terrain."]},"American modernism":{"why":"Simplified, flattened forms and bold color applied to urban or regional American subjects mark American modernism, c. 1910–1960, United States.","cues":["Hard-edged, simplified architectural or industrial forms.","Flat planes of clean, unmodulated color.","Stark, precisely lit scenes with geometric stillness."]},"Documentary photography":{"why":"Gritty black-and-white images of everyday hardship and social reality mark documentary photography, c. 1920–1960, United States and Europe.","cues":["High-contrast black-and-white tonal range.","Candid, unposed figures in real environments.","Weathered faces, poverty, and working-class settings."]},"Peredvizhniki":{"why":"Earthy, realist scenes of Russian peasant life and vast landscapes painted with somber, naturalistic color mark the Peredvizhniki, c. 1870–1923, Russia.","cues":["Muted, earthy palette of browns, grays, and greens.","Peasants, serfs, and common people as central subjects.","Brooding, expansive Russian landscape under heavy skies."]},"American Impressionism":{"why":"Sun-drenched, loose brushwork capturing fleeting light and leisure marks American Impressionism, c. 1880–1915, United States.","cues":["Broken, feathery brushstrokes of bright, warm color.","Dappled sunlight on figures, gardens, and water.","Outdoor leisure scenes with soft, dissolved edges."]},"Flemish Baroque":{"why":"Dramatic chiaroscuro, fleshy figures, and lush surface textures mark Flemish Baroque painting, c. 1585–1700, Flanders.","cues":["Deep shadows contrasting with brilliantly lit flesh.","Robust, full-bodied figures with glowing skin.","Rich textures: silk, fur, armor, and abundant fruit."]},"Mughal painting":{"why":"Fine, jewel-like detail, layered opaque pigment, and courtly subjects mark Mughal painting, c. 1560–1750, India.","cues":["Miniature scale with hair-thin brushwork detail.","Vivid, saturated color on cream or tinted paper.","Figures in profile within ornate garden or court settings."]},"Literati painting":{"why":"Spare ink wash, rough dry brushwork, and scholarly subjects mark Literati painting, c. 1050–1900, China.","cues":["Monochrome or limited ink tones on paper or silk.","Dry, scratchy brushstrokes prizing texture over finish.","Bamboo, rocks, orchids, and misty mountain landscapes."]},"Venetian Renaissance":{"why":"Warm, glowing color, rich oil glazes, and sensuous light mark the Venetian Renaissance, c. 1400–1600, Venice, Italy.","cues":["Deep, luminous color built through layered oil glazes.","Soft, atmospheric light dissolving crisp outlines.","Lush fabrics, golden tones, and idealized figures."]},"Gothic art":{"why":"Soaring verticality, pointed arches, and jewel-toned stained glass mark Gothic art, c. 1140–1520, Europe.","cues":["Elongated figures with elegant, swaying postures.","Gold leaf backgrounds dissolving earthly space.","Pointed arches, tracery, and rose windows throughout."]},"Rinpa":{"why":"Bold decorative forms, lavish gold-leaf grounds, and nature motifs mark Rinpa, c. 1600–1900, Japan.","cues":["Flat gold or silver leaf as dominant background.","Stylized plants, waves, and birds with crisp outlines.","Rich, saturated pigments pooled in tarashikomi wet-on-wet technique."]},"Japonisme":{"why":"Flat color planes, cropped compositions, and Japanese motifs absorbed into Western art mark Japonisme, c. 1860–1900, Europe.","cues":["Asymmetrical, boldly cropped compositions with high horizon lines.","Flat unmodulated color areas replacing Western chiaroscuro.","Fans, blossoms, kimono patterns, and wave forms as décor."]},"Dutch Golden Age painting":{"why":"Meticulous realism, dramatic tonal contrast, and everyday subject matter mark Dutch Golden Age painting, c. 1580–1700, Netherlands.","cues":["Deep shadow and warm light in tight tonal range.","Textures — silk, bread crust, pewter — rendered with precision.","Domestic interiors, still-life tables, and merchant portraits dominate."]},"Hellenistic art":{"why":"Extreme emotion, twisting bodies, and theatrical drama mark Hellenistic art, c. 323–31 BCE, Greece and the Mediterranean.","cues":["Contorted, spiraling poses straining in multiple directions.","Anguished or ecstatic facial expressions with furrowed brows.","Deep undercutting in sculpture creating dramatic shadow and movement."]},"Persian miniature":{"why":"Jewel-bright palette, flat tilted space, and intricate patterned surfaces mark Persian miniature painting, c. 1300–1600, Iran.","cues":["Lapis lazuli blue and vermilion dominating saturated flat backgrounds.","High tilted ground plane with no Western perspective recession.","Every surface — carpet, garden, robe — dense with fine pattern."]},"Classicism":{"why":"Ordered, idealized figures in balanced compositions with cool, clear light mark Classicism, c. 1600–1840, Europe.","cues":["Smooth, sculptural figures with idealized anatomy.","Restrained palette of cool grays, blues, and earth tones.","Symmetrical, architectural compositions with clear depth."]},"Luminism":{"why":"Glassy, mirrorlike water and invisible brushwork dissolving into radiant light mark Luminism, c. 1850–1875, United States.","cues":["Perfectly still water reflecting a luminous sky.","Brushwork so smooth the surface appears polished.","Wide, low horizon with vast, hazy atmospheric sky."]},"Kanō school":{"why":"Bold ink brushwork on gold-leaf backgrounds with pine, tiger, and dragon motifs mark the Kanō school, c. 1450–1900, Japan.","cues":["Gleaming gold-leaf or gold-wash backgrounds.","Strong, confident ink brushwork for rocks and foliage.","Iconic motifs: pine trees, bamboo, tigers, dragons."]},"Yamato-e":{"why":"Brilliant flat color, bird's-eye interiors, and flowing narrative scenes on scrolls mark Yamato-e, c. 900–1900, Japan.","cues":["Rooftops removed to reveal interiors from above.","Flat, jewel-bright color with fine gold line detail.","Continuous narrative scenes unrolling across horizontal scrolls."]},"Romanesque":{"why":"Thick-walled stone churches, rounded arches, and flattened hieratic figures mark Romanesque art, c. 1000–1200, Europe.","cues":["Heavy rounded arches and barrel-vaulted stone interiors.","Flat, elongated figures with large, stylized eyes.","Dense interlace ornament and biting beast motifs."]},"Arts and Crafts":{"why":"Handcrafted objects with visible construction, flat botanical ornament, and rich earth tones mark Arts and Crafts, c. 1860–1920, Britain, Europe, and North America.","cues":["Stylized, flat plant forms — leaves, flowers, vines.","Warm earth tones: ochre, forest green, brick red.","Visible joinery and handmade texture prized over machine finish."]},"Geometric Abstraction":{"why":"Pure geometric shapes — squares, circles, grids — in primary colors and black and white mark Geometric Abstraction, c. 1910–1940, Europe.","cues":["Hard-edged squares, rectangles, circles — no organic curves.","Primary colors plus black, white, and gray only.","Flat, unmodulated color with no shadow or texture."]},"Red-figure pottery":{"why":"Reserved terracotta-red figures against a black glaze ground with fine interior line detail mark red-figure pottery, c. 530–320 BCE, Greece.","cues":["Red-orange figures on a glossy jet-black background.","Fine painted interior lines showing muscle and drapery folds.","Mythological and athletic figures in dynamic, naturalistic poses."]},"International Gothic":{"why":"Elegant elongated figures, jewel-like color, and courtly ornament mark International Gothic, c. 1375–1425, Europe.","cues":["Sinuous, S-curved figures in flowing gold-trimmed robes.","Dense patterned backgrounds of punched gold leaf.","Delicate botanical and animal details in margins."]},"Rajput painting":{"why":"Vivid flat color, lyrical line, and devotional or romantic subjects mark Rajput painting, c. 1600–1850, India.","cues":["Hot, saturated reds, yellows, and greens in flat planes.","Slender figures with large almond-shaped eyes in profile.","Lush garden settings with flowering trees and monsoon skies."]},"Russian Symbolism":{"why":"Dreamlike, mystical imagery, moody color, and decorative flatness mark Russian Symbolism, c. 1880–1910, Russia.","cues":["Pale, phosphorescent or deeply saturated unnatural color.","Flattened forms with sinuous Art Nouveau-influenced outlines.","Otherworldly figures — demons, angels, visions — in hazy space."]},"Modernism":{"why":"Radical fragmentation, abstraction, and rejection of illusionistic space mark Modernism, c. 1900–1945, Europe and North America.","cues":["Fractured or flattened forms breaking from naturalistic anatomy.","Bold, non-descriptive color divorced from observed reality.","Experimental compositions collapsing depth into flat picture plane."]},"Russian Realism":{"why":"Somber naturalism, grey-brown palette, and unflinching scenes of peasant and social life mark Russian Realism, c. 1860–1900, Russia.","cues":["Muted earthy palette of greys, browns, and dull greens.","Carefully observed working-class and rural figures in natural light.","Wide horizontal compositions evoking the vast Russian steppe."]},"Constructivism":{"why":"Bold geometric shapes, primary colors, and dynamic diagonal compositions mark Constructivism, c. 1915–1935, Russia.","cues":["Hard-edged triangles, circles, and rectangles.","Stark red, black, and white palette.","Diagonal lines creating urgent, machine-age energy."]},"Heidelberg School":{"why":"Sun-drenched Australian landscape painted with loose, bright brushwork marks the Heidelberg School, c. 1886–1900, Australia.","cues":["Bleached golden light flooding wide open bush.","Broken, confident brushstrokes of Impressionist touch.","Eucalyptus scrub, dusty plains, and blue distances."]},"Ashcan School":{"why":"Gritty urban street life painted in dark, earthy tones with raw brushwork marks the Ashcan School, c. 1900–1915, United States.","cues":["Tenement alleys, saloons, and crowded city crowds.","Dark, smoky palette of brown, grey, and black.","Thick, slashing brushstrokes conveying working-class energy."]},"Russian Revival":{"why":"Medieval Slavic ornament, onion-dome motifs, and jewel-bright folk pattern mark Russian Revival, c. 1860–1920, Russia.","cues":["Dense interlaced geometric and floral folk ornament.","Rich jewel tones — cobalt, crimson, and gold.","Kokoshnik arches and bogatyr warrior imagery."]},"Barbizon school":{"why":"Quiet, overcast forest interiors and peasant fields painted in muted, earthy tones mark the Barbizon school, c. 1830–1875, France.","cues":["Soft, silvery light filtering through dense woodland.","Warm brown and olive green tonal palette.","Thick, textured paint capturing rough bark and soil."]},"Nanga":{"why":"Loose, scholarly ink brushwork with poetic inscriptions in the Chinese literati tradition marks Nanga, c. 1700–1900, Japan.","cues":["Dry, scratchy ink strokes on silk or paper.","Sparse mountain landscapes with misty negative space.","Calligraphic poem or inscription integrated into composition."]},"Bird-and-flower painting":{"why":"Delicate birds and blossoms rendered with precise brushwork on silk or paper mark bird-and-flower painting, c. 900–1900, China.","cues":["Minutely observed plumage with fine ink-line detail.","Soft washes of pink, white, and pale green.","Single branch composition with abundant negative space."]},"Ptolemaic Egypt":{"why":"Traditional Egyptian flat relief blended with subtle Greek stylization and monumental temple scale marks Ptolemaic Egypt, c. 305–30 BCE.","cues":["Hieroglyphic-covered temple walls in low raised relief.","Egyptian gods rendered with slightly softer, rounder faces.","Flat profile figures in ochre, blue, and terracotta."]},"Black-figure pottery":{"why":"Silhouetted black figures incised with fine detail against orange clay mark black-figure pottery, c. 700–500 BCE, Greece.","cues":["Glossy black slip figures on terracotta orange ground.","Incised lines scratch detail into black silhouettes.","Friezes of warriors, gods, and athletes in profile."]},"Futurism":{"why":"Splintered, motion-streaked forms conveying speed and mechanical energy mark Futurism, c. 1909–1944, Italy.","cues":["Repeated overlapping lines suggest rapid movement.","Sharp, angular fragmentation of figures and machines.","Electric palette of acid yellows, oranges, and blues."]},"Aestheticism":{"why":"Languid figures, muted harmony of tone, and decorative surface beauty mark Aestheticism, c. 1860–1900, United Kingdom.","cues":["Soft, silvery or olive palette with jewel accents.","Loosely draped classical robes on elongated figures.","Objects — fans, peacock feathers, blue-and-white pottery — as motifs."]},"Greek Classical":{"why":"Idealized, anatomically balanced human figures in marble with restrained drapery mark Greek Classical art, c. 480–323 BCE, Greece.","cues":["Smooth marble with naturalistic but idealized musculature.","Contrapposto stance — weight shifted onto one leg.","Thin, clinging drapery that reveals body beneath."]},"Pahari painting":{"why":"Brilliant jewel-toned pigments, lyrical line, and Krishna devotional scenes mark Pahari painting, c. 1690–1820, India.","cues":["Intense flat color — cobalt blue, vermillion, leaf green.","Sinuous outline describing graceful, slender figures.","Lush forest or monsoon landscape as romantic backdrop."]},"Bauhaus":{"why":"Primary colors, geometric form, and the marriage of fine art with functional design mark Bauhaus, 1919–1933, Germany.","cues":["Circles, squares, and triangles as primary visual vocabulary.","Red, yellow, and blue with black and white only.","Clean, unornamented surfaces that show material directly."]},"Naïve Art":{"why":"Flat, unmodeled forms, bright unmixed color, and childlike spatial logic mark Naïve Art, c. 1880–1940, Europe.","cues":["Figures and objects outlined with even, simple contours.","No linear perspective — near and far objects same size.","High-key, unblended colors applied in flat patches."]},"City Beautiful movement":{"why":"Grand civic axes, gleaming Beaux-Arts domes, and monumental symmetry mark the City Beautiful movement, c. 1890–1920, United States.","cues":["White neoclassical facades, colonnades, and domes.","Broad tree-lined boulevards with formal axial symmetry.","Fountains, plazas, and heroic sculptural programs."]},"Cubo-Futurism":{"why":"Shattered, overlapping planes fused with blur and speed lines mark Cubo-Futurism, c. 1912–1916, Russian avant-garde and Europe.","cues":["Fragmented geometric facets colliding across the surface.","Motion blur and repeated contours suggesting rapid movement.","Harsh, discordant colors splitting fractured mechanical forms."]},"Flemish Still-Life Painting":{"why":"Lavish accumulations of food, flowers, and luxury objects rendered with jewel-like precision mark Flemish Still-Life Painting, c. 1600–1680, Southern Netherlands.","cues":["Deep, velvety darkness contrasting brilliant lit surfaces.","Hyper-detailed textures — dewdrops, petal veins, fur.","Overflowing arrangements of game, fruit, silver, and crystal."]},"Proto-Renaissance":{"why":"Emerging three-dimensionality and natural human weight emerging from gold-ground Byzantine flatness mark Proto-Renaissance painting, c. 1280–1400, Italy.","cues":["Gold-leaf backgrounds with figures gaining bodily volume.","Drapery beginning to fold and fall with physical weight.","Faces showing tentative emotion beyond stylized icon masks."]},"Safavid Persian miniature":{"why":"Luminous flat color, sinuous figures in lush garden settings, and gold-flecked skies mark Safavid Persian miniature painting, c. 1501–1736, Iran.","cues":["Brilliant lapis, vermillion, and gold with no cast shadows.","High horizon tilting the ground plane toward the viewer.","Flowing robes, blossoming trees, and intricate patterned borders."]},"Ilkhanid art":{"why":"Chinese-influenced brushy landscapes fused with Islamic manuscript tradition and dynamic figural energy mark Ilkhanid art, 1256–1335, Iran.","cues":["East Asian ink-style clouds and rocks in Persian manuscripts.","Crowded, energetic battle scenes with Mongol dress and armor.","Bold diagonal compositions breaking earlier static page formats."]},"Neo-Impressionism":{"why":"Systematic grids of uniform color dots creating optical color mixing through scientific method mark Neo-Impressionism, c. 1886–1906, France.","cues":["Tiny, equal-sized dots or mosaic strokes of pure color.","Luminous, almost buzzing surface from optical color blending.","Calm, freeze-frame compositions with stiff, silhouetted figures."]},"Chinese literati painting":{"why":"Spare, expressive ink brushwork on paper or silk with prominent calligraphic inscription marks Chinese literati painting, c. 11th–20th century, China.","cues":["Dry, scratchy ink strokes prizing spontaneity over finish.","Minimal pale ink wash leaving vast areas of bare silk.","Columns of calligraphy and seal impressions as composition."]},"Ming dynasty painting":{"why":"Ink-wash landscapes with dramatic mist, meticulous bird-and-flower detail, and refined brushwork mark Ming dynasty painting, c. 1368–1644, China.","cues":["Layered ink washes creating misty, receding mountains.","Precise, decorative color in bird-and-flower compositions.","Calligraphic brushstrokes integrated with poetry inscriptions."]},"Tosa school":{"why":"Jewel-bright mineral pigments, gold leaf, and courtly Yamato-e narratives mark Tosa school painting, c. 1400–1900, Japan.","cues":["Intense opaque mineral colors — red, green, gold.","Rooftops removed to reveal interior court scenes.","Delicate fine-line figures in classical Heian costume."]},"Pictorialism":{"why":"Soft-focus, painterly photographs with misty tones and blurred edges mark Pictorialism, c. 1885–1915, Europe/United States.","cues":["Deliberately blurred, hazy atmospheric focus overall.","Warm sepia, platinum, or muted grey tonal range.","Compositional borrowings from painting — allegorical figures, landscapes."]},"Maruyama-Shijō school":{"why":"Naturalistic observation combined with fluid, spontaneous brushwork and pale washes mark Maruyama-Shijō school painting, c. 1750–1900, Japan.","cues":["Soft, diluted ink washes with minimal hard outlines.","Accurately observed animals and plants from direct study.","Sketchy, energetic brushwork against empty, unpainted ground."]},"Abbasid":{"why":"Luster-glazed ceramics, animated human figures, and intricate geometric or arabesque ornament mark Abbasid art, 750–1258, Iran/Mesopotamia.","cues":["Metallic gold and copper luster glaze on white ceramic.","Stiff, frontal human figures with large expressive eyes.","Dense interlacing vegetal and geometric surface ornament."]},"Grand Manner":{"why":"Large-scale figures in heroic poses, rich drapery, and dramatic chiaroscuro mark the Grand Manner, c. 1700–1800, Britain.","cues":["Life-size or larger figures in classical or noble dress.","Deep shadow contrasted with warm, luminous flesh tones.","Theatrical sky, column, or landscape backdrop."]},"Attic red-figure pottery":{"why":"Red clay figures reserved against a glossy black ground mark Attic red-figure pottery, c. 530–300 BCE, Athens.","cues":["Warm terracotta figures on a jet-black painted field.","Fine painted lines defining muscles, drapery folds, hair.","Mythological or athletic figures in profile or three-quarter view."]},"Nihonga":{"why":"Refined mineral pigments on silk or paper with delicate line and quiet color mark Nihonga, c. 1900–1960, Japan.","cues":["Soft, chalky mineral colors with subtle gradation.","Fine, controlled brushline defining form sparingly.","Traditional motifs — birds, blossoms, figures — on silk or washi."]},"Vienna Secession":{"why":"Sinuous gold ornament, flattened form, and erotic symbolism mark Vienna Secession work, c. 1897–1920, Austria.","cues":["Gold leaf or gold paint integrated into the surface.","Flat, mosaic-like geometric and spiral patterning.","Stylized, elongated figures merging with decorative ground."]},"Abstract art":{"why":"Non-representational form, pure color, and line liberated from visible reality mark Abstract art, c. 1910–1970, Europe.","cues":["No recognizable objects — only shape, color, and line.","Flat planes or gestural marks as the sole subject.","Composition structured by visual rhythm, not narrative."]},"German Realism":{"why":"Sober palette, meticulous surface detail, and unidealized working or bourgeois subjects mark German Realism, c. 1840–1895.","cues":["Muted, earthy tones with precise material textures.","Ordinary domestic or labor scenes rendered without sentiment.","Strong, even light revealing every fabric and surface detail."]},"Song dynasty painting":{"why":"Misty, recession-filled landscapes with ink wash and vast negative space mark Song dynasty painting, c. 960–1279, China.","cues":["Mountains dissolving into pale, atmospheric ink mist.","Tiny human figures dwarfed by monumental landscape.","Large unpainted silk or paper as active empty space."]},"Zen ink painting":{"why":"Rapid, spare brushstrokes in black ink with bold empty space mark Zen ink painting, c. 1300–1600, Japan and China.","cues":["Swift, spontaneous brushwork in monochrome black ink.","Extreme economy — a few strokes convey the whole form.","Vast blank ground surrounding a minimal central motif."]},"Greek Archaic":{"why":"Rigid frontal or striding figures with the signature 'Archaic smile' mark Greek Archaic art, c. 700–480 BCE, Greece.","cues":["Stiff, symmetrical human figures with clenched fists.","Faint, formulaic smile on otherwise blank faces.","Hair rendered as flat, decorative parallel ridges or curls."]},"Attic black-figure pottery":{"why":"Silhouetted black figures with incised interior detail on orange-red clay mark Attic black-figure pottery, c. 700–300 BCE, Greece.","cues":["Glossy black slip figures on warm terracotta ground.","Fine incised lines scratching anatomy through the black.","Mythological and athletic scenes in friezes or medallions."]},"Attic black-figure":{"why":"Silhouetted black slip figures with incised interior lines on red-orange clay mark Attic black-figure, c. 620–480 BCE, Attica, Greece.","cues":["Crisp incised lines defining muscles and drapery folds.","Added red and white pigments accent details on black figures.","Narrative mythological scenes banded around vessel forms."]},"Italo-Byzantine":{"why":"Gold-saturated grounds, rigid frontal figures, and stylized drapery mark Italo-Byzantine painting, c. 1200–1350, Italy.","cues":["Flat gold leaf backgrounds with no depth.","Elongated figures with large, staring eyes.","Drapery rendered as stiff, decorative line patterns."]},"Ancient Roman":{"why":"Illusionistic space, naturalistic portraiture, and narrative relief sculpture mark Ancient Roman art, c. 100 BCE–300 CE, Europe.","cues":["Highly realistic facial features with individual wrinkles.","Continuous narrative scenes wrapped around relief friezes.","Trompe-l'oeil architectural painting with receding space."]},"Archaic Greek sculpture":{"why":"Rigid frontal stance, stylized almond eyes, and the fixed 'Archaic smile' mark Greek sculpture, c. 700–480 BCE, Greece.","cues":["Stiff, symmetrical pose with arms at sides.","Hair rendered as flat, beaded parallel ridges.","Slight upward curve of lips — the Archaic smile."]},"Northern Mannerism":{"why":"Exaggerated elongation, contorted poses, acidic color, and crowded compositions mark Northern Mannerism, c. 1520–1600, Northern Europe.","cues":["Impossibly long necks and limbs twisted into spirals.","Jarring palette of lime green, acid yellow, and cold pink.","Figures compressed into restless, overcrowded picture planes."]},"Russian Avant-Garde":{"why":"Pure geometric abstraction, bold primaries, and machine-age flatness mark the Russian Avant-Garde, c. 1910–1930, Russia.","cues":["Hard-edged rectangles, circles, and diagonals dominate.","Flat red, black, and white with no tonal modeling.","Dynamic diagonal compositions suggesting speed and force."]},"American Genre Painting":{"why":"Warm anecdotal scenes of everyday rural or small-town life rendered in detailed naturalism mark American Genre Painting, c. 1830–1880, United States.","cues":["Ordinary figures caught mid-action in familiar settings.","Warm amber and golden light bathing interior scenes.","Meticulous surface detail on clothing, tools, and wood grain."]},"Canadian Modernism":{"why":"Bold, sweeping brushwork, saturated color, and vast northern wilderness landscapes mark Canadian Modernism, c. 1910–1930, Canada.","cues":["Thick, rhythmic paint strokes follow rolling landforms.","Intense jewel-toned lakes, skies, and autumn foliage.","Panoramic compositions with no human figures present."]},"Spanish Baroque":{"why":"Dramatic chiaroscuro, earthy palette, and intense religious gravity mark Spanish Baroque, c. 1600–1700, Spain and Spanish-ruled Naples.","cues":["Deep shadow swallowing figures from below.","Muted ochres, blacks, and raw whites dominate.","Austere, unidealized faces with piercing realism."]},"Qing dynasty painting":{"why":"Refined ink-wash landscapes, Orthodox literati brushwork, and eccentric individualist styles mark Qing dynasty painting, c. 1644–1912, China.","cues":["Layered ink washes building misty mountain depth.","Spare, expressive brushstrokes on silk or paper.","Inscriptions, red seals, and colophons crowding the composition."]},"Seljuk":{"why":"Geometric interlace, bold Kufic script bands, and buff-colored stucco or brick ornament mark Seljuk art, 1037–1194, Iran and Anatolia.","cues":["Star-polygon geometric grids carved in stucco.","Angular Kufic script as primary decorative border.","Unglazed or turquoise-accented terracotta surfaces."]},"Meiji era":{"why":"Hybrid East-West styles, precision lacquerwork and cloisonné for export, and Western-influenced oil painting mark Meiji era art, 1868–1912, Japan.","cues":["Intricate cloisonné enamel with jewel-like color fields.","Western perspective and shading in Japanese-subject oil painting.","Elaborate export lacquer with dense gold nashiji grounds."]},"Greek Geometric art":{"why":"Dense bands of meanders, zigzags, and schematic human figures mark Greek Geometric art, c. 900–700 BCE, Greece.","cues":["Lustrous black-and-buff painted pottery with horizontal registers.","Stick-figure mourners and horse-drawn funeral processions.","Every surface filled with repeating geometric pattern."]},"French Classicism":{"why":"Rational clarity, cool palette, and Greco-Roman subjects arranged in shallow, ordered space mark French Classicism, c. 1600–1700, France and Rome.","cues":["Crisp, sculptural figures in antique drapery.","Balanced, frieze-like horizontal composition with architectural backdrop.","Clear, cool light with firm contours and restrained color."]},"French Gothic":{"why":"Soaring pointed arches, luminous stained glass, and elongated stone figures mark French Gothic art, c. 1150–1400, Europe.","cues":["Jewel-toned rose and lancet windows flooding interiors with color.","Tall, columnar figures with gentle S-curve and drapery folds.","Ribbed vaulting and tracery dissolving walls into light."]},"Italian Gothic":{"why":"Gold-ground panel painting with Byzantine solemnity softened by nascent naturalism marks Italian Gothic art, c. 1250–1400, Europe.","cues":["Burnished gold leaf background with punched decorative tooling.","Tender facial expressions and emerging three-dimensional drapery.","Pointed arch frames and elaborate gilt wood altarpiece structure."]},"School of Paris":{"why":"Expressive color, loose painterly surfaces, and modernist figure distortion across many national styles mark the School of Paris, c. 1900–1940, Paris.","cues":["Thickly worked or fluid paint with visible gestural brushwork.","Elongated, distorted, or flattened figures in intimate settings.","Rich, emotive color freed from strict naturalistic description."]},"Swedish Naturalism":{"why":"Quiet, light-filled realism painted outdoors with a cool Nordic palette marks Swedish Naturalism, c. 1880–1920, Sweden.","cues":["Cool silvery-grey and muted green tones.","Soft, even daylight with minimal dramatic shadow.","Rural figures, forests, and snow-covered landscapes."]},"French Baroque":{"why":"Monumental compositions, theatrical chiaroscuro, and grand classical architecture mark French Baroque, c. 1600–1700, France.","cues":["Deep shadow sliced by strong directional light.","Heavy drapery in rich reds, golds, and blues.","Ordered, symmetrical compositions with heroic figures."]},"Skagen Painters":{"why":"Brilliant coastal light, white-sand beaches, and plein-air brushwork mark the Skagen Painters, c. 1870–1920, Denmark.","cues":["Dazzling Northern seaside light bleaching the scene.","Loose, confident brushwork capturing wind and sun.","Fishermen, dunes, and blue-white sky meeting sea."]},"Der Blaue Reiter":{"why":"Intense non-naturalistic color, spiritual abstraction, and expressive line mark Der Blaue Reiter, c. 1911–1914, Munich, Germany.","cues":["Pure, unmodulated color freed from natural appearance.","Simplified, near-abstract figures and landscape forms.","Horses, riders, and bold color as emotional symbol."]},"Russian Constructivism":{"why":"Geometric abstraction, industrial materials, and dynamic diagonal compositions mark Russian Constructivism, c. 1913–1935, Russia/Soviet Union.","cues":["Hard-edged triangles, circles, and rectangles in red and black.","Bold diagonal lines creating urgent visual energy.","Machine-age lettering and photomontage integrated into design."]},"American Luminism":{"why":"Glassy, suffused light, mirror-calm water, and invisible brushwork mark American Luminism, c. 1850–1900, United States.","cues":["Perfectly smooth surface with no visible brushstrokes.","Golden atmospheric haze dissolving the horizon line.","Still water reflecting vast, luminous open skies."]},"Qing dynasty Chinese painting":{"why":"Ink wash, calligraphic brushwork, and scholar-literati subjects mark Qing dynasty Chinese painting, c. 1644–1911, China.","cues":["Monochrome or lightly tinted ink on paper or silk.","Expressive, varied brushstrokes conveying texture and spirit.","Mountains, bamboo, rocks, and poetic inscriptions integrated."]},"Roman Third Style":{"why":"Delicate, flat architectural frames on solid-color walls mark Roman Third Style painting, c. 20 BCE–20 CE.","cues":["Solid black, red, or white wall panels dominate.","Slender, impossibly thin ornamental columns decorate borders.","Small, jewel-like landscape or figure panels at center."]},"Cretan school":{"why":"Elongated figures, Byzantine gold grounds, and intense spiritual expressiveness mark Cretan school icon painting, c. 1450–1700.","cues":["Attenuated, flame-like figures with angular drapery highlights.","Rich gold or gold-ochre background throughout.","Deep shadows and sharp white highlights model gaunt faces."]},"Late Gothic":{"why":"Soaring verticality, intricate gold detail, and expressive elongated figures mark Late Gothic art, c. 1350–1500, Europe.","cues":["Gold leaf backgrounds with tooled, punched patterns.","Figures with swirling, deeply folded drapery.","Pointed arches, tracery, and ornate decorative borders."]},"Sienese School":{"why":"Luminous gold grounds, tender Madonna types, and refined linear elegance mark the Sienese School, c. 1250–1550, Siena, Italy.","cues":["Brilliant gold leaf backgrounds and halos.","Delicate, lyrical line with soft pastel flesh tones.","Large-eyed, gentle Madonna and Child compositions."]},"Goryeo dynasty":{"why":"Translucent celadon glaze, refined inlaid decoration, and Buddhist iconographic refinement mark Goryeo dynasty art, c. 918–1392, Korea.","cues":["Jade-green celadon glaze with cool, glassy surface.","Delicate inlaid white and black slip floral patterns.","Slender, elegant Buddhist figures in gilt bronze."]},"Attic red-figure":{"why":"Red clay figures on a black glaze ground with incised interior detail mark Attic red-figure, c. 530–300 BCE, Athens.","cues":["Warm terracotta-red figures against glossy jet-black ground.","Fine painted interior lines defining anatomy and drapery.","Mythological scenes with dynamic, overlapping figures."]},"Grand Manner portraiture":{"why":"Full-length scale, classical props, and heroic atmospheric settings mark Grand Manner portraiture, c. 1720–1800, Britain and colonial America.","cues":["Life-size figures set against stormy skies or columns.","Rich silk, satin, and velvet rendered with lustrous sheen.","Antique architectural fragments or sweeping landscape backdrops."]},"American Neoclassicism":{"why":"White marble or painted stone surfaces, strict symmetry, and Greco-Roman forms mark American Neoclassicism, c. 1780–1840, North America.","cues":["Smooth white marble with cool, idealized surface finish.","Pediments, colonnades, and triangular temple façades.","Draped figures with calm, generalized classical features."]},"American Romanticism":{"why":"Vast luminous wilderness, dramatic light, and tiny human figures mark American Romanticism, c. 1820–1880, North America.","cues":["Panoramic landscapes with glowing, golden atmospheric light.","Minute human figures dwarfed by mountains or rivers.","Precise botanical detail contrasting with sublime storm skies."]},"American folk art":{"why":"Flat, unmodeled forms, bold pattern, and vernacular subjects mark American folk art, c. 1700–1950, United States.","cues":["Simplified shapes with no illusionistic shading.","Strong decorative patterning and saturated color.","Everyday rural life, portraits, and painted objects."]},"Social documentary photography":{"why":"Stark black-and-white images of poverty, labor, and urban life mark social documentary photography, c. 1890–1945, United States and Europe.","cues":["High-contrast monochrome with deep shadow.","Worn faces, cramped rooms, and working hands.","Candid, close framing that crowds the subject."]},"École de Paris":{"why":"Emotionally charged color, loose brushwork, and solitary figures mark the École de Paris, c. 1905–1940, Paris, France.","cues":["Expressive, dragged impasto and raw brushstrokes.","Distorted, elongated figures with melancholy presence.","Muted earth tones punctuated by vivid acid color."]},"Amsterdam Impressionism":{"why":"Dark tonal palette, thick impasto, and rain-soaked urban scenes mark Amsterdam Impressionism, c. 1880–1910, Netherlands.","cues":["Heavy, loaded brushwork with visible ridges of paint.","Subdued grays, browns, and greens dominate.","Canals, bridges, and city streets in overcast light."]},"History painting":{"why":"Large-scale, multi-figure compositions dramatizing historical, mythological, or biblical events mark history painting, c. 1600–1880, Europe and North America.","cues":["Grand format with heroic, idealized human figures.","Theatrical diagonal composition and dramatic lighting.","Classical drapery, armor, and architectural settings."]},"Victorian art":{"why":"Highly finished surfaces, moral or narrative subjects, and eclectic historical styles mark Victorian art, c. 1837–1901, Britain.","cues":["Meticulous, near-photographic surface detail throughout.","Richly costumed figures in anecdotal or sentimental scenes.","Dense, cluttered compositions with jewel-like color."]},"Danube School":{"why":"Lush, atmospheric forest landscape dominating small figures marks the Danube School, c. 1500–1530, southern Germany and Austria.","cues":["Towering trees and dense foliage fill the picture plane.","Warm golden-green light filters through woodland canopy.","Tiny figures dwarfed by wild, untamed natural setting."]},"Utrecht Caravaggism":{"why":"Raking candlelight, half-length figures crowding the picture plane, and deep shadow mark Utrecht Caravaggism, c. 1610–1630, Utrecht, Dutch Republic.","cues":["Single artificial light source cuts through dense darkness.","Large half-length figures pressed close to the viewer.","Rough skin, feathered hats, and genre-scene subjects."]},"Dutch Naturalism":{"why":"Muted, earthy tones and humble rural subjects painted with honest, unidealized brushwork mark Dutch Naturalism, c. 1880–1920, Netherlands.","cues":["Palette of grey, brown, and dull green.","Flat polders, windmills, and peasant laborers.","Thick, workmanlike brushwork with no glamour."]},"American Tonalism":{"why":"Soft, unified veils of a single muted tone dissolved into misty, near-monochromatic mood pictures mark American Tonalism, c. 1880–1915, United States.","cues":["Near-monochrome palette of silver, olive, or gold.","Hazy edges where forms dissolve into atmosphere.","Still water, twilight skies, and lone bare trees."]},"German Impressionism":{"why":"Loose, energetic brushwork with deeper, more saturated color than French Impressionism and a preference for interior drama marks German Impressionism, c. 1890–1930, Germany.","cues":["Rich, warm color with heavier, more emphatic strokes.","Strong tonal contrasts alongside broken dabs of light.","Garden scenes, portraits, and bourgeois interiors."]}},"culture":{"Qing dynasty":{"why":"Refined ink landscapes, decorative porcelain with cobalt-blue or famille rose palette, and eclectic scholarly subjects mark Qing dynasty art, 1644–1912, China.","cues":["Vibrant famille rose or cobalt-blue porcelain surfaces.","Loose, expressive ink brushwork on silk or paper.","Ornate decorative borders with floral and dragon motifs."]},"New Kingdom":{"why":"Elegant, elongated figures in strict composite pose, rich polychrome pigments, and hieroglyphic registers mark New Kingdom Egyptian art, c. 1550–1070 BCE.","cues":["Slender, refined figures with graceful proportions.","Brilliant blues, golds, and reds in flat register scenes.","Elaborate tomb paintings with gods and ritual processions."]},"Third Intermediate Period":{"why":"Stiffer, more schematic figures, increased use of bronze and gilded coffins, and densely packed funerary decoration mark Third Intermediate Period Egyptian art, c. 1070–664 BCE.","cues":["Densely packed hieroglyphic and figural surface decoration.","Richly gilded, elaborately painted wooden coffins.","Stiffer, more formulaic human figures than New Kingdom."]},"Safavid":{"why":"Jewel-toned manuscript illustrations with intricate gold detailing, arabesque borders, and courtly figural scenes mark Safavid art, 1501–1736, Iran.","cues":["Lapis lazuli blue and gold leaf throughout compositions.","Sinuous arabesque and floral patterned borders.","Delicate, small-scale courtly figures in garden settings."]},"Edo period":{"why":"Flat color, bold outline, and floating-world subjects mark Edo period art, 1615–1868, Japan.","cues":["Flat areas of pure color with no Western shading.","Strong black contour lines defining figures and forms.","Actors, courtesans, landscapes, and Mt. Fuji motifs."]},"Neolithic Chinese jade":{"why":"Smooth, muted green stone worked into ritual shapes marks Neolithic Chinese jade, c. 4500–1500 BCE, China.","cues":["Polished green, gray-green, or white nephrite surface.","Simple geometric forms: discs, tubes, and blades.","Minimal decoration; form and material carry meaning."]},"Roman":{"why":"Illusionistic space, naturalistic portraiture, and marble or fresco surfaces mark Roman art, c. 500 BCE–500 CE, Roman Empire.","cues":["Hyper-realistic facial portraits with individual features.","Architectural fresco settings creating deep, painted space.","White marble sculpture with idealized yet lifelike anatomy."]},"Iznik":{"why":"Brilliant white ground, cobalt blue, and bold floral arabesques on glazed ceramics mark Iznik ware, c. 1480–1700, Turkey.","cues":["Stark white tin-glazed ground with vivid blue and red.","Swirling tulips, carnations, and saz leaves in repeat.","Tomato-red pigment raised slightly above the glaze surface."]},"Middle Kingdom":{"why":"Refined composite figures, formal registers, and warm limestone palette mark Middle Kingdom Egyptian art, c. 2055–1650 BCE.","cues":["Figures shown with head in profile, shoulders frontal.","Horizontal registers stacking scenes across the surface.","Earthy ochre, terracotta, and muted blue-green pigments."]},"Goryeo Korean":{"why":"Translucent celadon glaze and inlaid crane or cloud motifs mark Goryeo Korean ceramics, 918–1392, Korea.","cues":["Soft blue-green celadon glaze of exceptional translucency.","White and black inlaid slip forming cranes, clouds, chrysanthemums.","Elegant, understated forms with subtly curved profiles."]},"Ottoman":{"why":"Geometric interlace, arabesque ornament, and dense polychrome pattern mark Ottoman art, c. 1300–1900, Turkey.","cues":["Interlocking geometric star patterns in rich color.","Flowing arabesque vine scrolls filling every surface.","Gold, deep red, cobalt, and black as dominant palette."]},"Moche":{"why":"Stirrup-spout vessels, narrative painted friezes, and portrait ceramics mark Moche culture, c. 100–800, Peru.","cues":["Cream and red-brown two-tone painted ceramic surfaces.","Highly realistic, individualized portrait faces on vessels.","Warrior, sacrifice, and deity scenes in continuous friezes."]},"Late Period Egypt":{"why":"Rigid archaism, hard stone surfaces, and strict canon revival mark Late Period Egypt, c. 664–332 BCE.","cues":["Stiff, frontal figures echoing Old Kingdom conventions.","Highly polished dark stone with sharp, precise carving.","Dense hieroglyphic inscription covering every available surface."]},"Ming dynasty":{"why":"Brilliant blue-and-white porcelain, monumental architecture, and vivid court painting mark Ming dynasty art, 1368–1644, China.","cues":["Cobalt-blue floral and dragon motifs on white porcelain.","Richly colored narrative figure paintings with fine brushwork.","Symmetrical, red-lacquered architectural forms with yellow-glazed tile roofs."]},"Song dynasty":{"why":"Misty monochrome ink landscapes, refined celadon ceramics, and contemplative emptiness mark Song dynasty art, 960–1279, China.","cues":["Vast empty space dominating ink-wash landscape compositions.","Soft, receding mountains dissolved in atmospheric mist.","Pale celadon and Ru-ware glazes in restrained, minimal forms."]},"Tang dynasty":{"why":"Robust figures, vivid polychrome sancai glazes, and cosmopolitan energy mark Tang dynasty art, 618–907, China.","cues":["Three-color lead glaze — amber, green, cream — on tomb figures.","Plump, full-bodied figures conveying vitality and worldly confidence.","Camels, horses, and Central Asian figures reflecting Silk Road exchange."]},"Kamakura Buddhist art":{"why":"Fierce realism, powerful muscular forms, and dramatic expression mark Kamakura Buddhist art, c. 1185–1333, Japan.","cues":["Intensely realistic anatomy with visible veins and tensed muscle.","Inlaid crystal eyes creating startling lifelike presence.","Guardian figures with exaggerated scowls and dynamic warrior poses."]},"Joseon Korean":{"why":"Spare ink landscapes, white porcelain, and restrained elegance mark Joseon Korean art, 1392–1897, Korea.","cues":["Ink wash landscapes with misty, unpainted negative space.","Pure white porcelain with minimal blue underglaze decoration.","Soft, muted palette emphasizing emptiness and stillness."]},"Predynastic Egypt":{"why":"Buff-clay pottery with dark geometric and animal bands, and small schematic figurines mark Predynastic Egypt, c. 5000–3100 BCE.","cues":["Red or buff clay vessels painted with dark geometric bands.","Silhouetted animals — hippos, birds, crocodiles — in rows.","Small, stylized human figurines with abstract, beak-like faces."]},"Edo peoples":{"why":"Cast-brass portrait heads with coral-bead collars and high-relief bronze plaques mark Edo peoples art, c. 1400–1900, Benin/Nigeria.","cues":["Gleaming cast-brass heads with serene, symmetrical faces.","Stacked coral-bead collars rising to the chin.","Rectangular bronze plaques with figures in shallow relief."]},"Maya":{"why":"Low-relief carved stone glyphs, corbelled stone vaults, and jade-and-feather regalia mark Maya art, c. 250–1000, Mesoamerica.","cues":["Dense carved hieroglyphic inscriptions covering stone surfaces.","Elaborately costumed figures draped in quetzal feathers and jade.","Corbelled limestone arches in stepped pyramid temples."]},"Inca":{"why":"Precise geometric abstraction in textile and stonework marks Inca art, c. 1400–1533, Peru.","cues":["Perfectly fitted polygonal stone masonry with no mortar.","Bold stepped and diamond tocapu grid patterns on textiles.","Burnished gold and silver ritual vessels in simple organic forms."]},"Islamic art":{"why":"Intricate geometric and vegetal ornament covering every surface marks Islamic art, c. 650–1500, Middle East and North Africa.","cues":["Endlessly repeating geometric star and polygon tessellations.","Flowing arabesque vine-and-leaf scrollwork filling all voids.","Elegant Arabic calligraphy integrated as primary decoration."]},"Han dynasty":{"why":"Fluid silhouette figures, earthy lacquer palette, and animated narrative friezes mark Han dynasty art, 206 BCE–220 CE, China.","cues":["Flat figures in swift, curving brushwork silhouettes.","Warm reds, blacks, and ochres on lacquer and painted tile.","Horizontal narrative registers of processions and hunting scenes."]},"Coptic art":{"why":"Frontally staring figures, flat earth tones, and Christian-Egyptian hybrid iconography mark Coptic art, c. 300–1000, Egypt.","cues":["Large, oversized frontal eyes dominating simplified faces.","Flat, undifferentiated color blocks with minimal modeling.","Interlaced vine and cross motifs on linen and stone."]},"Byzantine":{"why":"Solemn frontal figures, gold mosaic ground, and hieratic scale mark Byzantine art, c. 330–1453, Byzantium and the Eastern Mediterranean.","cues":["Shimmering gold tesserae background flattening all space.","Rigid frontal saints with elongated faces and stylized drapery folds.","Inverse perspective making sacred figures loom over architecture."]},"Muromachi Buddhist art":{"why":"Monochrome ink wash, spare asymmetric composition, and Zen-influenced emptiness mark Muromachi Buddhist art, c. 1336–1573, Japan.","cues":["Wet-ink wash gradations from deep black to bare white paper.","Minimal brushwork figures dissolving into mist and void.","Diagonal asymmetric compositions with large unpainted silences."]},"Kongo":{"why":"Power-figure forms studded with nails or shells, and expressive carved faces mark Kongo art, c. 1400–1900, Central Africa.","cues":["Wooden figures densely embedded with iron nails and blades.","Strongly carved facial grimaces with bared teeth.","Bilaterally symmetrical standing posture with clenched fists."]},"Roman Egypt":{"why":"Realistic encaustic portrait faces fused onto Egyptian mummy wrappings mark Roman Egypt, c. 30 BCE–390 CE.","cues":["Lifelike, dark-eyed face painted in hot wax.","Roman dress and jewellery on Egyptian mummy case.","Warm flesh tones with strong shadow and highlight."]},"Old Kingdom":{"why":"Rigid, hierarchical figures in strict profile on flat stone relief mark the Old Kingdom, c. 2686–2160 BCE, Egypt.","cues":["Head and legs in profile, eye and torso frontal.","Registers of flat figures stacked in strict tiers.","Incised limestone relief with earth-red and ochre color."]},"Kamakura period":{"why":"Intense, muscular realism in wooden sculpture and vivid narrative hand-scrolls mark the Kamakura period, 1185–1333, Japan.","cues":["Fierce warrior or deity with crystal-inlaid eyes.","Dynamic ink hand-scrolls with rapid battle scenes.","Layered wood with deep-cut, swirling drapery folds."]},"Dogon people":{"why":"Elongated, angular wooden figures with raised arms and abstract geometric scarification marks Dogon art, c. 1400–present, Mali.","cues":["Tall, ladder-like human forms with upraised arms.","Rough-hewn wood with geometric surface scarification patterns.","Granary doors carved with stacked rows of ancestors."]},"Heian Buddhist art":{"why":"Gilded, serene deity figures on silk with jewel-like pigments mark Heian Buddhist art, c. 794–1185, Japan.","cues":["Gold leaf and rich mineral pigments on silk.","Symmetrical, frontal seated Buddhas with halo.","Delicate ink-drawn mandala geometric frameworks."]},"Heian period":{"why":"Flowing robes in layered pastel color, delicate line, and aristocratic interiors mark Heian period painting, 794–1185, Japan.","cues":["Overlapping kimonos in soft, graded color bands.","Flat forms with no cast shadows or modeling.","Courtly scenes viewed from a high, tilted angle."]},"Qajar art":{"why":"Large-eyed frontal portraits, dense floral ornament, and lacquer-bright color mark Qajar art, 1789–1925, Iran.","cues":["Arched brows, almond eyes, and thin joining mustache.","Jewel-encrusted costumes against flat patterned grounds.","Lacquerwork and oil on canvas with hard, glossy finish."]},"Yuan dynasty":{"why":"Dry, expressive brushwork in ink, scholar-rocks, and bamboo on paper mark Yuan dynasty painting, 1271–1368, China.","cues":["Sparse ink washes with visible, calligraphic brushstrokes.","Twisted rocks and bare-branched trees as primary subjects.","Large areas of unpainted paper as active negative space."]},"Neo-Hittite art":{"why":"Low-relief basalt friezes of striding figures and hybrid beasts mark Neo-Hittite art, c. 1200–700 BCE, Anatolia and northern Syria.","cues":["Flat basalt orthostats carved in shallow profile relief.","Heraldic lions, sphinxes, and eagle-headed guardians.","Figures with stiff, marching legs and frontal torsos."]},"Chimú":{"why":"Burnished black ceramic vessels and sheet-metal regalia with repeated geometric and deity friezes mark Chimú art, c. 900–1470, Peru.","cues":["Matte-black polished ceramics with stirrup-spout forms.","Repetitive frieze patterns of waves, birds, and fish.","Hammered gold and silver sheet with embossed figures."]},"Luba":{"why":"Serene scarified female figures with elaborate coiffures supporting royal ceremonial objects mark Luba art, c. 1700–1900, DR Congo.","cues":["Smooth dark wood with intricate raised scarification patterns.","Elaborate carved headdresses crowning calm, downcast faces.","Female caryatid figures bearing stools, headrests, or staffs."]},"Shang–Zhou bronze":{"why":"Dense, symmetrical taotie masks and interlocking zoomorphic bands covering ritual vessels mark Shang–Zhou bronze art, c. 1600–256 BCE, China.","cues":["Dark green-grey patinated cast bronze with thick walls.","All-over horror vacui relief of interlocking animal motifs.","Prominent glaring taotie face dominating vessel bodies."]},"Sumerian":{"why":"Rigidly frontal figures with enormous inlaid eyes, and carved votive registers mark Sumerian art, c. 4500–1900 BCE, Mesopotamia.","cues":["Wide, staring shell-and-lapis inlaid eyes on statuettes.","Horizontal registers of identical marching figures in relief.","Stocky, cylindrical bodies with hands clasped at the chest."]},"Etruscan":{"why":"Vivid banquet scenes, bold terracotta figures, and Archaic smiling faces mark Etruscan art, c. 700–100 BCE, Etruria/Italy.","cues":["Bright flat reds, blacks, and ochres on tomb walls.","Archaic almond eyes and upturned 'Etruscan smile.'","Elongated bronze figures and detailed terracotta sarcophagi."]},"Tang dynasty Buddhist art":{"why":"Full-bodied, voluptuous figures with serene faces and rich mineral pigments mark Tang dynasty Buddhist art, c. 618–907, China.","cues":["Rounded, fleshy forms draped in flowing, layered robes.","Brilliant mineral blues, greens, and reds in polychrome.","Elaborate floral halos and ornate heavenly attendants."]},"Northern Qi Buddhist art":{"why":"Thin, transparent robes clinging to simplified cylindrical bodies and serene elongated faces mark Northern Qi Buddhist art, c. 534–581, North China.","cues":["Single thin robe rendered as subtle surface ridges only.","Smooth, columnar body with minimal anatomical detail.","Calm oval face with heavy-lidded, downcast eyes."]},"Himalayan peoples":{"why":"Bold geometric patterns in wool textiles, animist deity masks, and raw natural materials mark Himalayan peoples' art, c. 1000–1900.","cues":["Vivid striped and geometric woven textile bands.","Fierce carved wooden masks with bulging eyes.","Hammered copper and silver ritual vessels and jewelry."]},"Tibet":{"why":"Symmetrical thangka compositions with jewel-colored deities, flame aureoles, and gold line detail mark Tibetan art, c. 1000–1900.","cues":["Central deity ringed by hierarchical smaller figures.","Saturated red, blue, and gold against dark grounds.","Intricate gold line patterning on robes and halos."]},"Teotihuacan":{"why":"Flat profile figures, talud-tablero architectural profiles, and symbolic feathered-serpent iconography in bold color mark Teotihuacan art, c. 100 BCE–750, Central Mexico.","cues":["Figures rendered in strict flat profile with no modeling.","Stepped talud-tablero platform forms in pale stone.","Repeated feathered serpent and rain-deity motifs in murals."]},"Neo-Assyrian":{"why":"Low-relief stone friezes of muscular narrative hunts, battles, and winged bull colossi mark Neo-Assyrian art, c. 911–609 BCE, Assyria/Mesopotamia.","cues":["Continuous narrative stone relief bands of war and hunting.","Precisely carved rippling musculature on human and animal forms.","Massive human-headed winged bull gateway guardians in limestone."]},"Warring States period":{"why":"Intricate interlaced dragons, vivid inlaid bronzes, and restless surface pattern mark Warring States art, c. 475–221 BCE, China.","cues":["Dense, coiling dragon and serpent interlace.","Bronze inlaid with turquoise, gold, or silver.","Lacquerware in bold red and black geometric bands."]},"Momoyama period":{"why":"Gold-leaf screens blazing with bold color and monumental nature motifs mark Momoyama painting, 1573–1615, Japan.","cues":["Vast gold-leaf grounds dissolving into cloud forms.","Flat, saturated mineral colors — green, blue, white.","Giant pine trees or birds dominating the composition."]},"Bamana":{"why":"Vertical, geometric wooden figures with abstract, angular limbs mark Bamana sculpture, c. 1400–1950, Mali.","cues":["Elongated torso with sharply angled arms and legs.","Encrusted, darkened surface from ritual sacrificial material.","Pointed or crested headdress rising from the figure."]},"Ethiopian Christian Art":{"why":"Large frontal eyes, flat gold grounds, and bold outline on religious figures mark Ethiopian Christian art, c. 400–1900.","cues":["Oversized, wide-open eyes dominating the face.","Flat, burnished gold leaf behind sacred figures.","Strong black outlines enclosing pure, unmodeled color areas."]},"Luristan bronze":{"why":"Highly stylized animal and fantastical creature forms cast in small bronze objects mark Luristan bronzes, c. 1000–650 BCE, western Iran.","cues":["Small cast-bronze objects: weapons, pins, finials.","Interlocked animals with exaggerated, curving limbs.","Openwork designs creating negative space within the metal."]},"Cypriot":{"why":"Simplified, votive limestone figures with flat, schematic features mark Cypriot sculpture, c. 1200–300 BCE, Cyprus.","cues":["Blocky limestone forms with minimal surface detail.","Large, almond-shaped eyes set in flat, mask-like faces.","Painted geometric and floral bands on pale ceramic surfaces."]},"Hindu temple sculpture":{"why":"Densely packed, sensuously curved deities with multiple arms and elaborate jewelry mark Hindu temple sculpture, c. 600–1300, India.","cues":["Sinuous triple-bend pose (tribhanga) in standing figures.","Multiple arms radiating symmetrically, each with attributes.","Rich surface carving: jewels, garlands, and headdresses."]},"Ancient Egypt":{"why":"Composite figures combining frontal torso with profile head and legs, in rigid hierarchic scale, mark Ancient Egyptian art, c. 3200–30 BCE.","cues":["Head in strict profile, eye drawn full-frontal.","Figures sized by social rank, not spatial depth.","Flat color fields in ochre, terracotta, turquoise, and black."]},"Timurid":{"why":"Luminous cobalt-and-gold manuscript illuminations with intricate geometric arabesques mark Timurid art, 1370–1507, Central Asia and Iran.","cues":["Ultra-fine brushwork with brilliant lapis-blue and gold.","Figures in landscape with high horizon and no cast shadows.","Densely patterned borders of interlaced vegetal scrollwork."]},"Islamic Egypt":{"why":"Arabesque scrollwork, Kufic or Naskh inscriptions, and geometric interlace on metalwork, textiles, and carved stone mark Islamic Egypt, c. 640–1500.","cues":["Flowing Arabic calligraphic bands as primary decoration.","Interlocking star-polygon geometric grids.","Tiraz-style striped silk with inscription borders."]},"Assyrian":{"why":"Large stone relief friezes of winged genii, royal hunts, and marching armies in rigid profile mark Assyrian art, c. 900–600 BCE, Mesopotamia.","cues":["Low-relief limestone slabs with precise musculature.","Figures in strict profile with detailed curled beards.","Repeated narrative registers of sieges and lion hunts."]},"Seljuq":{"why":"Turquoise and cobalt glazed geometric tilework, bold Kufic script, and vegetal interlace mark Seljuq art, 1037–1194, Iran and Anatolia.","cues":["Monochrome turquoise or cobalt glaze on molded ceramic.","Angular Kufic script integrated into geometric ornament.","Stucco surfaces with deeply undercut arabesque relief."]},"Kubachi":{"why":"Loosely painted figures in landscape with soft polychrome slips under a crackled glaze mark Kubachi wares, c. 1300–1650, Iran.","cues":["Crackled, glassy transparent glaze over the entire surface.","Soft, sketchy figures amid floral sprays and foliage.","Palette of grey-blue, sage green, and brick red on white slip."]},"Northern Wei Buddhist art":{"why":"Elongated, ethereal figures, flame-edged robes, and flat linear drapery mark Northern Wei Buddhist art, c. 386–534, North China.","cues":["Thin, weightless bodies with serene downcast faces.","Cascading robe hems fanning out in sharp points.","Shallow relief carving with crisp, calligraphic line."]},"Veracruz":{"why":"Smiling ceramic figures, yoke-and-palma stone regalia, and scrolling interlace ornament mark Veracruz art, c. 300–900, Mexico.","cues":["Hollow clay figures with broad, beaming smiles.","U-shaped stone yokes with dense relief carving.","Elaborate scrollwork borders framing all surfaces."]},"Shang dynasty":{"why":"Dark bronze vessels dense with taotie masks and geometric registers mark Shang dynasty art, c. 1600–1046 BCE, China.","cues":["Symmetrical animal-face motif — the taotie — dominates surfaces.","Dense, layered geometric bands cover every inch of bronze.","Deep green or black patina on heavy ritual vessels."]},"Yoruba":{"why":"Naturalistic bronze and terracotta heads, beaded regalia, and frontal symmetry mark Yoruba art, c. 1100–1900, Nigeria.","cues":["Serene, idealized faces with parallel scarification lines.","Elaborate beaded crowns covering the entire face and head.","Smooth, polished bronze surfaces with fine incised detail."]},"Akan (Asante)":{"why":"Gleaming cast gold, geometric kente textile patterns, and small brass goldweights mark Akan (Asante) art, c. 1700–1900, Ghana.","cues":["Solid gold or gilt regalia with bold, repoussé surfaces.","Tiny brass figures cast as miniature narrative goldweights.","Bright kente woven in strict geometric color blocks."]},"Khmer":{"why":"Dense sandstone bas-relief, serene frontal deity figures, and towering lotus-bud spires mark Khmer art, c. 600–1400, Cambodia.","cues":["Flat, densely packed narrative relief bands.","Smooth, idealized faces with a subtle downward smile.","Multi-tiered temple towers with corbelled stone profiles."]},"Persian Islamic pottery":{"why":"Cobalt-and-turquoise glazes, dense arabesque and figural decoration, and fine fritware bodies mark Persian Islamic pottery, c. 800–1700, Iran.","cues":["Brilliant cobalt, turquoise, and white slip grounds.","Interlaced vegetal scrolls and seated court figures.","Lustre-painted metallic sheen over white glaze."]},"Olmec":{"why":"Colossal helmeted basalt heads, jade celts, and smooth, fleshy monumental carving mark Olmec art, c. 1500–400 BCE, Mexico.","cues":["Massive, rounded basalt portrait heads with flat noses.","Polished jade figurines in blue-green tones.","Were-jaguar motif blending infant face with feline snarl."]},"Parthian":{"why":"Frontal figures with large staring eyes, stiff patterned garments, and mixed Greek-Iranian iconography mark Parthian art, c. 247 BCE–224 CE, Iran and Mesopotamia.","cues":["Rigid frontal stance replacing classical contrapposto.","Oversized, wide-open eyes dominating the face.","Elaborately patterned textile folds rendered as flat lines."]},"Hittite":{"why":"Blocky orthostatic relief slabs, striding lion and sphinx gate-guardians, and hieroglyphic-inscribed stone mark Hittite art, c. 1650–1200 BCE, Anatolia.","cues":["Massive lion or sphinx figures flanking stone gateways.","Low-relief figures with schematic, angular musculature.","Hieroglyphic Luwian inscriptions carved into basalt."]},"Edo Buddhist art":{"why":"Gilded lacquer altarpieces, polychrome wooden sculpture, and elaborate mandala compositions mark Edo Buddhist art, c. 1615–1868, Japan.","cues":["Densely gilded wood sculpture with lacquered surface.","Wrathful deities surrounded by flame-halo mandorlas.","Rich red, gold, and black lacquer altar furnishings."]},"Achaemenid":{"why":"Processional relief friezes of tribute-bearers, polished limestone or glazed brick, and hybrid guardian figures mark Achaemenid art, 550–330 BCE, Iran and Persia.","cues":["Long files of identical tribute-bearers in low relief.","Winged bull lamassu with human heads at entrances.","Highly polished stone with crisp, regularized drapery folds."]},"Kofun period":{"why":"Terracotta haniwa cylinders and figures, keyhole-shaped burial mounds, and plain reddish earthenware mark Kofun period art, c. 250–538, Japan.","cues":["Hollow terracotta haniwa figures in unglazed red clay.","Simple, schematic faces with punched circular eyes.","Cylindrical base forms topped with human or animal shapes."]},"Wari":{"why":"Interlocking geometric figures in vivid repeated grids mark Wari art, c. 500–1000, Peru.","cues":["Bold, angular staff-bearer figures in tapestry weave.","High-contrast palette of red, yellow, blue, and black.","Symmetrical, modular repetition across textile surfaces."]},"Aztec (Mexica)":{"why":"Massive stone sculpture dense with calendrical and sacrificial imagery marks Aztec (Mexica) art, c. 1325–1521, Mexico.","cues":["Hard-edged, monumental carving in dark volcanic stone.","Skulls, serpents, solar discs, and clawed earth-goddess forms.","Compressed, flat-relief figures packed with symbolic detail."]},"Anatolia":{"why":"Hybrid animal-and-human protomes, hammered metalwork, and Near Eastern-meets-Greek ornament mark Anatolian art, c. 700 BCE–300 CE, Turkey.","cues":["Gleaming bronze and silver vessels with griffin or lion handles.","Blended Greek, Persian, and local motifs in one object.","Intricate inlay and granulation on jewelry and fittings."]},"Baule":{"why":"Serene, symmetrical wooden figures with elaborate coiffures and scarification marks mark Baule art, c. 1700–1900, Ivory Coast.","cues":["Smooth, dark-patinated wood with fine surface detail.","Downcast eyes, composed expression, and upright posture.","Elaborate braided headdress and geometric scarification patterns."]},"Joseon dynasty":{"why":"Restrained ink brushwork, white porcelain, and scholarly nature subjects mark Joseon dynasty art, c. 1392–1910, Korea.","cues":["Milky white porcelain with spare cobalt-blue decoration.","Loose, expressive ink wash of bamboo, plum, or mountains.","Asymmetrical, breath-filled composition with much empty space."]},"Song dynasty Buddhist art":{"why":"Softly modeled, serene bodhisattva figures in fluid drapery mark Song dynasty Buddhist art, c. 960–1279, China.","cues":["Polychromed wood with traces of gilding and lacquer.","Relaxed 'royal ease' posture with one knee raised.","Diaphanous layered robes with delicate linear folds."]},"Ethiopian art":{"why":"Frontal saints with enormous almond eyes, flat gold ground, and bold outline mark Ethiopian art, c. 1300–1900, Ethiopia.","cues":["Brilliant red, blue, and gold on vellum or wood panel.","Rigid frontal figures with oversized, staring eyes.","Geometric border patterns framing sacred narrative scenes."]},"Newar art":{"why":"Rich gilt metal, jewel-toned pigments, and densely detailed Buddhist and Hindu deity forms mark Newar art, c. 1100–1800, Nepal.","cues":["Gleaming gilded bronze with intricate repoussé detail.","Deep red, gold, and black dominating the palette.","Multi-armed deities with elaborate crowns and aureoles."]},"Central Tibet":{"why":"Symmetrical thangka compositions, flat jewel colors, and mandala-structured deity figures mark Central Tibetan painting, c. 1200–1700, Tibet.","cues":["Flat, saturated colors with fine gold line detail.","Central deity ringed by smaller figures in strict hierarchy.","Ornate flaming aureoles and lotus throne bases."]},"Fatimid":{"why":"Lively figural imagery, lustrous ceramic glaze, and intricate vegetal arabesque mark Fatimid art, 909–1171, Egypt/North Africa.","cues":["Metallic golden-brown lusterware glaze on ceramic.","Animated human and animal figures in sinuous outline.","Dense interlocking arabesque and scrolling vine ornament."]},"Tolita-Tumaco":{"why":"Expressive ceramic figurines with detailed headdresses and bold facial modeling mark Tolita-Tumaco culture, c. 600 BCE–400 CE, Ecuador/Colombia.","cues":["Hand-modeled terracotta with burnished tan-grey surface.","Highly expressive faces with individualized features.","Elaborate headdresses and ornamental ear and nose rings."]},"Pompeian Roman":{"why":"Illusionistic architectural vistas, vivid fresco color, and trompe-l'œil spatial depth mark Pompeian Roman painting, c. 100 BCE–79 CE, Roman Italy.","cues":["Bold Pompeian red and black panel backgrounds.","Painted columns and niches creating false architecture.","Mythological figures rendered with soft modeled shading."]},"Minoan":{"why":"Fluid, energetic line and vivid marine or nature motifs mark Minoan art, c. 3000–1100 BCE, Crete.","cues":["Sinuous, flowing contours around figures and animals.","Bright blue, ochre, and red on white or dark grounds.","Octopus, dolphins, lilies, and bull-leaping scenes."]},"Yuan dynasty Buddhist art":{"why":"Monumental robed figures, rich Tibetan-inflected iconography, and fine ink-and-gold detail mark Yuan Buddhist art, c. 1271–1368, China.","cues":["Dense, layered deity figures with multiple arms or heads.","Gold line against deep blue or red lacquered grounds.","Elaborate flame mandorlas and intricate lotus thrones."]},"Chola bronze":{"why":"Sinuous lost-wax bronze figures with jeweled detail and dynamic posture mark Chola sculpture, c. 850–1250, India.","cues":["Warm, lustrous dark bronze surface throughout.","Slim waist, full hips, and elegant contrapposto stance.","Elaborate crown, jewelry, and flame-like surrounding aureole."]},"Dvaravati":{"why":"Serene, broad-featured Buddha images in pale stone or stucco mark Dvaravati art, c. 550–1000 CE, Central Thailand.","cues":["Wide, flat face with thick brow ridge and broad nose.","Robes rendered as thin, clinging ridged lines.","Limestone or pale sandstone with matte, weathered surface."]},"Classical Greek":{"why":"Idealized, anatomically balanced marble figures and red-figure narrative pottery mark Classical Greek art, c. 480–323 BCE.","cues":["Poised, naturalistic human bodies with calm expression.","Red figures on black gloss, or black on red, ceramic ground.","Architectural orders with precise fluting and acanthus ornament."]},"Jain art":{"why":"Richly pigmented manuscript pages, naked or jeweled Tirthankara figures, and geometric cosmological diagrams mark Jain art, c. 500–1700, India.","cues":["Vivid opaque palette: scarlet, gold, ultramarine, green.","Elongated eye projecting beyond the face's profile.","Serene standing figures with rigid, symmetrical frontality."]},"Proto-Elamite":{"why":"Incised cylinder-seal imagery of fantastical animals and early pictographic script marks Proto-Elamite art, c. 3200–2700 BCE, Iran.","cues":["Miniature incised animals in repeated, frieze-like registers.","Creatures shown with twisted, part-human postures.","Buff or grey clay tablets and seals with geometric pictographs."]},"Cycladic":{"why":"Stark white marble idols with abstracted, featureless faces mark Cycladic art, c. 3200–2000 BCE, the Aegean.","cues":["Pure white marble with smooth, almost unbroken surface.","Flat, folded-arm female form reduced to geometry.","Featureless face save a single raised triangular nose."]},"Akkadian":{"why":"Tightly modeled bronze and stone portraits with elaborate braided beards and victory narratives mark Akkadian art, c. 2334–2154 BCE, Mesopotamia.","cues":["Intricately carved, coiled beard in precise parallel ridges.","Stacked register scenes of warriors and captive figures.","Stern, frontal royal face with large inlaid or incised eyes."]},"Late Period Egyptian":{"why":"Hard, highly polished dark stone statuary with archaizing canonical forms mark Late Period Egyptian art, c. 664–332 BCE.","cues":["Jet-black or dark green stone with mirror-smooth finish.","Rigid frontal pose with one foot slightly advanced.","Crisp hieroglyphic inscription covering base and back pillar."]},"Muromachi period":{"why":"Spare ink-wash landscapes, dramatic empty space, and Zen-inflected brushwork mark Muromachi period art, 1336–1573, Japan.","cues":["Monochrome ink washes dissolving into misty white space.","Jagged, abbreviated brushstrokes for rocks and pines.","Steep, cropped mountain peaks emerging from fog."]},"Bamileke people":{"why":"Bold geometric beadwork, monumental figurative sculpture, and royal regalia color mark Bamileke art, c. 1850–1950, Cameroon.","cues":["Dense mosaic of glass beads in red, blue, and white.","Large-headed figures with powerful, stocky proportions.","Spider or elephant motifs signaling royal authority."]},"Sui dynasty Buddhist art":{"why":"Rigid frontality, thin linear drapery, and serene iconic faces mark Sui dynasty Buddhist art, c. 581–618, China.","cues":["Symmetrical, stiff frontal poses on lotus pedestals.","Thin, schematic drapery with shallow parallel folds.","Gilded bronze surfaces with elongated, calm faces."]},"Djenné":{"why":"Earthen terracotta figures, kneeling postures, and encrusted surfaces mark Djenné art, c. 1100–1500, Mali.","cues":["Coarse reddish-brown terracotta with pitted, encrusted texture.","Figures kneeling or crouching in compressed, tense poses.","Raised bumps or scarification patterns covering the body."]},"Ngbandi":{"why":"Bold scarification patterns, dynamic figural stance, and dark polished wood mark Ngbandi art, c. 1880–1920, northwestern DRC.","cues":["Dark, smooth hardwood with high-polish finish.","Prominent raised scarification lines on face and torso.","Figures with alert, forward-tilting, energetic posture."]},"Sogdian art":{"why":"Vivid narrative friezes with frontal figures, rich jewel-toned color, and hybrid East-West motifs mark Sogdian art, c. 400–800, Central Asia.","cues":["Flat, bright registers of red, blue, and gold.","Frontally posed figures with almond-shaped eyes.","Feasting, hunting, and mythic beasts on painted walls."]},"Punic":{"why":"Terracotta masks, geometric stelae with crescent-and-disc symbols, and Near Eastern hybrid motifs mark Punic art, c. 800–146 BCE, Carthage and Tunisia.","cues":["Grimacing terracotta masks with exaggerated features.","Carved stone stelae with schematic human silhouettes.","Crescent moon and solar disc repeated as sacred symbols."]},"Old Babylonian":{"why":"Baked-clay plaques with frontal nude figures and cuneiform-inscribed steles mark Old Babylonian art, c. 2000–1600 BCE, Mesopotamia.","cues":["Molded terra-cotta reliefs with flat, frontal bodies.","Stiff, layered register compositions on stone steles.","Horned divine headdresses and rod-and-ring symbols."]},"Amarna period":{"why":"Elongated skulls, soft rounded limbs, and naturalistic domestic scenes mark the Amarna period, c. 1353–1336 BCE, Egypt.","cues":["Distinctively elongated heads and full, pendulous lips.","Soft bellies, wide hips, and languid curved postures.","Sunrays ending in human hands descend from the Aten."]}}};
for(var k in G){C[k]=C[k]||{};for(var m in G[k]){if(!C[k][m])C[k][m]=G[k][m];}}})();
